const sageScroller=$('.sage-depth__scroller'),sageImages=$$('.sage-depth__image'),sageIntro=$('.sage-depth__intro'),sageOutro=$('.sage-depth__outro'),sageProgress=$('.sage-depth__progress b'),sageOutput=$('.sage-depth__progress output');
