let sageFrame=0,sageCurrent=0,sageTarget=0;
function readSageProgress(){const max=sageScroller.scrollHeight-sageScroller.clientHeight;return max?sageScroller.scrollTop/max:0}
function renderSageDepth(){sageFrame=0;const difference=sageTarget-sageCurrent;sageCurrent+=difference*(reduced.matches?1:.13);if(Math.abs(difference)<.00015)sageCurrent=sageTarget;const p=sageCurrent,clamp01=n=>Math.max(0,Math.min(1,n)),smooth=t=>t*t*(3-2*t);sageImages.forEach((item,i)=>{const start=+item.dataset.start,duration=.36,raw=(p-start)/duration,t=clamp01(raw),approach=smooth(t),x=+item.dataset.x*(.72+approach*.28),y=+item.dataset.y,z=-2600+approach*2920,rotation=+item.dataset.r*(1-approach*.45),fadeIn=smooth(clamp01(t/.16)),fadeOut=1-smooth(clamp01((t-.84)/.16));item.style.opacity=fadeIn*fadeOut;item.style.transform=`translate(-50%,-50%) translate3d(${x}vw,${y}vh,${z}px) rotateZ(${rotation}deg)`;item.style.zIndex=String(10+i)});sageIntro.style.opacity=String(1-clamp01(p/.07));sageIntro.style.transform=`translateY(${-p*110}px)`;const outro=clamp01((p-.94)/.055);sageOutro.style.opacity=String(outro);sageOutro.style.transform=`translateY(${(1-outro)*35}px)`;sageProgress.style.transform=`scaleX(${p})`;sageOutput.value=`${Math.round(p*100).toString().padStart(2,'0')}%`;if(sageCurrent!==sageTarget)sageFrame=requestAnimationFrame(renderSageDepth)}
