// Chromium can omit deeply transformed cards from elementsFromPoint. Resolve the
// projected rectangles ourselves, then choose the visually highest matching card.
function vaultCardAt(x,y){const contains=(r,pad=0)=>r&&x>=r.left-pad&&x<=r.right+pad&&y>=r.top-pad&&y<=r.bottom+pad;if(vaultVisualCard&&(contains(vaultVisualCard.getBoundingClientRect(),6)||contains(vaultRestRects.get(vaultVisualCard),6)))return vaultVisualCard;return vaultCards.filter(card=>contains(vaultVisualCard?vaultRestRects.get(card):card.getBoundingClientRect())).sort((a,b)=>(parseInt(getComputedStyle(b).zIndex)||0)-(parseInt(getComputedStyle(a).zIndex)||0))[0]||null}
const svgNS='http://www.w3.org/2000/svg',vaultTrailEl=document.createElementNS(svgNS,'svg');
vaultTrailEl.setAttribute('class','vault-trail');
const vaultTrailLength=16,vaultTrailPoints=[],vaultTrailSegments=[];
for(let i=0;i<vaultTrailLength;i++)vaultTrailPoints.push({x:0,y:0});
for(let i=0;i<vaultTrailLength-1;i++){const segment=document.createElementNS(svgNS,'line'),taper=1-i/(vaultTrailLength-1);segment.setAttribute('stroke-width',(3.2*taper+.4).toFixed(2));segment.setAttribute('stroke-opacity',(taper*.9+.05).toFixed(2));vaultTrailEl.append(segment);vaultTrailSegments.push(segment)}
document.body.append(vaultTrailEl);
const vaultFineHover=matchMedia('(hover:hover) and (pointer:fine)');
let vaultTrailRaw={x:0,y:0},vaultTrailOn=false,vaultTrailFrame=0;
function renderVaultTrail(){const head=vaultTrailPoints[0];head.x+=(vaultTrailRaw.x-head.x)*.42;head.y+=(vaultTrailRaw.y-head.y)*.42;for(let i=1;i<vaultTrailLength;i++){const point=vaultTrailPoints[i],ahead=vaultTrailPoints[i-1];point.x+=(ahead.x-point.x)*.34;point.y+=(ahead.y-point.y)*.34}let span=0;for(let i=0;i<vaultTrailSegments.length;i++){const a=vaultTrailPoints[i],b=vaultTrailPoints[i+1],segment=vaultTrailSegments[i];segment.setAttribute('x1',a.x.toFixed(1));segment.setAttribute('y1',a.y.toFixed(1));segment.setAttribute('x2',b.x.toFixed(1));segment.setAttribute('y2',b.y.toFixed(1));span+=Math.hypot(b.x-a.x,b.y-a.y)}if(vaultTrailOn||span>1)vaultTrailFrame=requestAnimationFrame(renderVaultTrail);else vaultTrailFrame=0;}
